"""
Visualization module for T037: Complexity vs. Performance Curves.

Generates plots showing pass rates against prompt complexity levels,
identifying inflection points (peak performance and diminishing returns).
"""
import os
import csv
from pathlib import Path
from typing import List, Dict, Any, Optional, Tuple
import matplotlib.pyplot as plt
import pandas as pd
import numpy as np

from config import Paths
from utils.logger import get_logger

logger = get_logger(__name__)


def load_execution_results_for_viz() -> pd.DataFrame:
    """Load execution results from the CSV generated by T030."""
    results_path = Paths.RESULTS / "execution_outcomes.csv"
    if not results_path.exists():
        raise FileNotFoundError(
            f"Execution results file not found at {results_path}. "
            "Ensure T030 (write_results) has been run successfully."
        )
    return pd.read_csv(results_path)


def calculate_aggregated_pass_rates(df: pd.DataFrame) -> pd.DataFrame:
    """
    Aggregate pass rates by complexity level.

    Returns a DataFrame with columns:
    - complexity_level: The complexity label (simple, moderate, etc.)
    - pass_rate: The proportion of passed samples (0.0 to 1.0)
    - count: Total number of samples in this level
    - passed_count: Number of passed samples
    """
    if df.empty:
        raise ValueError("Input DataFrame is empty; cannot calculate pass rates.")

    # Ensure complexity_level is treated as categorical with correct order
    complexity_order = [
        "simple", "moderate", "complex", "very_complex", "degenerate"
    ]
    df["complexity_level"] = pd.Categorical(
        df["complexity_level"], categories=complexity_order, ordered=True
    )

    # Group by complexity level and calculate pass rates
    aggregated = (
        df.groupby("complexity_level", observed=True)
        .agg(
            count=("execution_status", "count"),
            passed_count=("execution_status", lambda x: (x == "pass").sum()),
        )
        .reset_index()
    )

    aggregated["pass_rate"] = aggregated["passed_count"] / aggregated["count"]

    # Sort by the defined complexity order
    aggregated = aggregated.sort_values("complexity_level")

    return aggregated


def identify_inflection_points(
    df: pd.DataFrame
) -> Dict[str, Tuple[str, float]]:
    """
    Identify inflection points in the complexity vs. performance curve.

    Returns a dictionary with:
    - 'peak_performance': (complexity_level, pass_rate)
    - 'diminishing_returns': (complexity_level, pass_rate)
      - The first level where the marginal gain in pass rate is negative or zero
        compared to the previous level.
    """
    if df.empty or len(df) < 2:
        logger.warning("Insufficient data to identify inflection points.")
        return {
            "peak_performance": (None, None),
            "diminishing_returns": (None, None),
        }

    levels = df["complexity_level"].tolist()
    rates = df["pass_rate"].tolist()

    # Find peak performance
    peak_idx = int(np.argmax(rates))
    peak_level = levels[peak_idx]
    peak_rate = rates[peak_idx]

    # Find diminishing returns: first point where rate does not increase from previous
    diminishing_idx = None
    for i in range(1, len(rates)):
        if rates[i] <= rates[i - 1]:
            diminishing_idx = i
            break

    if diminishing_idx is not None:
        dim_level = levels[diminishing_idx]
        dim_rate = rates[diminishing_idx]
    else:
        # If performance keeps increasing, mark the last point
        dim_level = levels[-1]
        dim_rate = rates[-1]

    return {
        "peak_performance": (peak_level, peak_rate),
        "diminishing_returns": (dim_level, dim_rate),
    }


def plot_complexity_performance_curve(
    aggregated_df: pd.DataFrame,
    inflection_points: Dict[str, Tuple[str, float]],
    output_path: Optional[Path] = None,
) -> None:
    """
    Generate a line plot of complexity vs. pass rate with inflection points marked.

    Args:
        aggregated_df: DataFrame with complexity_level and pass_rate columns.
        inflection_points: Dict containing 'peak_performance' and 'diminishing_returns' tuples.
        output_path: Optional Path to save the figure. If None, saves to data/results/.
    """
    if output_path is None:
        output_path = Paths.RESULTS / "complexity_vs_performance.png"
    else:
        output_path = Path(output_path)

    # Ensure directory exists
    output_path.parent.mkdir(parents=True, exist_ok=True)

    fig, ax = plt.subplots(figsize=(10, 6))

    # Plot line and markers
    ax.plot(
        aggregated_df["complexity_level"],
        aggregated_df["pass_rate"],
        marker="o",
        linestyle="-",
        linewidth=2,
        markersize=8,
        label="Pass Rate",
        color="#1f77b4",
    )

    # Add grid
    ax.grid(True, linestyle="--", alpha=0.7)
    ax.set_xlabel("Prompt Complexity Level", fontsize=12)
    ax.set_ylabel("Pass Rate", fontsize=12)
    ax.set_title("Complexity vs. Code Generation Performance", fontsize=14, fontweight="bold")
    ax.set_ylim(0, 1.05)

    # Mark peak performance
    peak_label, peak_rate = inflection_points["peak_performance"]
    if peak_label:
        peak_idx = aggregated_df[aggregated_df["complexity_level"] == peak_label].index[0]
        ax.scatter(
            [peak_label], [peak_rate],
            color="green", s=100, zorder=5, label=f"Peak Performance ({peak_label:.2f})"
        )
        ax.annotate(
            f"Peak: {peak_label}\n({peak_rate:.2f})",
            xy=(peak_label, peak_rate),
            xytext=(peak_label, peak_rate + 0.1),
            ha="center",
            arrowprops=dict(arrowstyle="->", color="green", lw=1.5),
            fontsize=10,
            bbox=dict(boxstyle="round,pad=0.3", facecolor="white", edgecolor="green", alpha=0.8),
        )

    # Mark diminishing returns
    dim_label, dim_rate = inflection_points["diminishing_returns"]
    if dim_label:
        dim_idx = aggregated_df[aggregated_df["complexity_level"] == dim_label].index[0]
        ax.scatter(
            [dim_label], [dim_rate],
            color="red", s=100, zorder=5, label=f"Diminishing Returns ({dim_label:.2f})"
        )
        ax.annotate(
            f"Diminishing Returns: {dim_label}\n({dim_rate:.2f})",
            xy=(dim_label, dim_rate),
            xytext=(dim_label, dim_rate - 0.15),
            ha="center",
            arrowprops=dict(arrowstyle="->", color="red", lw=1.5),
            fontsize=10,
            bbox=dict(boxstyle="round,pad=0.3", facecolor="white", edgecolor="red", alpha=0.8),
        )

    ax.legend(loc="lower right")
    plt.xticks(rotation=0)
    plt.tight_layout()
    plt.savefig(output_path, dpi=300)
    plt.close(fig)

    logger.info(f"Visualization saved to {output_path}")


def write_inflection_summary_to_csv(
    inflection_points: Dict[str, Tuple[str, float]],
    output_path: Optional[Path] = None,
) -> None:
    """
    Write inflection point findings to a CSV file for record-keeping.

    Args:
        inflection_points: Dict with 'peak_performance' and 'diminishing_returns' tuples.
        output_path: Optional Path to save the CSV. If None, saves to data/results/.
    """
    if output_path is None:
        output_path = Paths.RESULTS / "inflection_points_summary.csv"
    else:
        output_path = Path(output_path)

    output_path.parent.mkdir(parents=True, exist_ok=True)

    rows = [
        {
            "metric": "peak_performance_level",
            "value": inflection_points["peak_performance"][0],
            "pass_rate": inflection_points["peak_performance"][1],
        },
        {
            "metric": "diminishing_returns_level",
            "value": inflection_points["diminishing_returns"][0],
            "pass_rate": inflection_points["diminishing_returns"][1],
        },
    ]

    with open(output_path, "w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=["metric", "value", "pass_rate"])
        writer.writeheader()
        writer.writerows(rows)

    logger.info(f"Inflection summary saved to {output_path}")


def main() -> None:
    """
    Main entry point for T037: Generate complexity vs. performance visualizations.

    1. Loads execution results from data/results/execution_outcomes.csv.
    2. Aggregates pass rates by complexity level.
    3. Identifies inflection points (peak performance, diminishing returns).
    4. Generates and saves a plot to data/results/complexity_vs_performance.png.
    5. Writes inflection point summary to data/results/inflection_points_summary.csv.
    """
    logger.info("Starting T037: Complexity vs. Performance Visualization")

    # Load data
    df = load_execution_results_for_viz()
    logger.info(f"Loaded {len(df)} execution results.")

    # Aggregate
    aggregated_df = calculate_aggregated_pass_rates(df)
    logger.info(f"Aggregated pass rates for {len(aggregated_df)} complexity levels.")

    # Identify inflection points
    inflection_points = identify_inflection_points(aggregated_df)
    logger.info(f"Identified inflection points: {inflection_points}")

    # Generate plot
    plot_complexity_performance_curve(aggregated_df, inflection_points)

    # Write summary CSV
    write_inflection_summary_to_csv(inflection_points)

    logger.info("T037 completed successfully.")


if __name__ == "__main__":
    main()